void vl_finish(const char* file, int line, const char*)
{
    if (current) current->log(LOGIC_LOG_INFO, std::string("$finish at ") + file + ":" + std::to_string(line));
    Verilated::threadContextp()->gotFinish(true);
}

void vl_fatal(const char* file, int line, const char*, const char* msg)
{
    Verilated::threadContextp()->gotError(true);
    Verilated::threadContextp()->gotFinish(true);
    if (current) current->log(LOGIC_LOG_ERROR, std::string(file) + ":" + std::to_string(line) + ": " + msg);
}

