bool verilator_build(const verilator_tools& tools, const verilator_job& job, const fs::path& cache_root, fs::path& plugin, std::string& error,
    std::vector<diagnostic>* diagnostics, const std::function<void(const std::string&)>& on_line)
{
    if (!check_job(tools, job, error)) return false;

    auto key = verilator_build_key(tools, job);
    plugin = verilator_plugin_path(cache_root, key);
    std::error_code ec;
    if (fs::is_regular_file(plugin, ec)) return true;

    // built in a temporary folder that becomes the cache entry at the end,
    // so an interrupted build never looks finished
    auto final_dir = plugin.parent_path();
    auto tmp = temp_folder(cache_root / "verilator", key + ".tmp-");
    if (tmp.empty()) {
        error = "can't create a folder in " + (cache_root / "verilator").string();
        return false;
    }
    struct cleanup {
        fs::path p;
        ~cleanup()
        {
            std::error_code ec;
            if (!p.empty()) fs::remove_all(p, ec);
        }
    } clean{tmp};

    if (on_line) on_line("building " + job.name + " with " + tools.version);

    // the ports in their order, the header of the model tells their types
    std::vector<model::port> ports;
    std::vector<model::param_def> params;
    std::string header;
    if (!describe(tools, job, ports, params, error, diagnostics, &header, on_line)) return false;
    auto wrapper = verilator_wrapper(job.impl.top, header, ports, error);
    if (wrapper.empty()) return false;
    if (!write_file(tmp / "logic_wrap.cpp", wrapper) || !write_file(tmp / "logic_model.h", sdk_header)) {
        error = "can't write the wrapper into " + tmp.string();
        return false;
    }

    // everything as a shared library with the wrapper as the "main"
    auto args = common_args(tools, job, tmp / "obj");
    auto jobs = std::max(1u, std::thread::hardware_concurrency());
    args.insert(args.end(), {"--cc", "--exe", "--build", "-j", std::to_string(jobs), (tmp / "logic_wrap.cpp").string()});
    args.insert(args.end(), {"-CFLAGS", "-fPIC -O2 -DVL_USER_FINISH -DVL_USER_FATAL -I" + tmp.string()});
    args.insert(args.end(), {"-LDFLAGS", "-shared -fPIC"});
    args.insert(args.end(), {"-o", plugin.filename().string()});
    if (!run_tool(args, error, diagnostics, on_line)) return false;

    auto built = tmp / "obj" / plugin.filename();
    if (!fs::is_regular_file(built, ec)) {
        error = "verilator didn't produce " + built.string();
        return false;
    }

    // the plugin alone is the cache entry
    auto staged = tmp / "entry";
    fs::create_directory(staged, ec);
    fs::rename(built, staged / plugin.filename(), ec);
    if (ec) {
        error = "can't move the plugin: " + ec.message();
        return false;
    }
    fs::rename(staged, final_dir, ec);
    if (ec && !fs::is_regular_file(plugin)) {
        error = "can't create " + final_dir.string() + ": " + ec.message();
        return false;
    }
    if (on_line) on_line("built " + plugin.string());
    return true;
}

